import { Router } from 'express';
import { z } from 'zod';
import { signIn, rotateApiKey } from '../services/auth.service';

export const authRouter = Router();

const credentials = z.object({
  email: z.string().email(),
  password: z.string().min(8),
});

authRouter.post('/auth/login', async (req, res) => {
  const parsed = credentials.safeParse(req.body);
  if (!parsed.success) {
    return res.status(400).json({ error: 'Invalid credentials payload' });
  }

  const session = await signIn(parsed.data.email, parsed.data.password);
  if (!session) {
    return res.status(401).json({ error: 'Email and password do not match' });
  }

  return res.json({ session });
});

authRouter.post('/auth/api-keys/rotate', async (req, res) => {
  const { currentKey } = req.body ?? {};
  const rotated = await rotateApiKey(String(currentKey ?? ''));
  return res.json({ apiKey: rotated });
});

export const loggingConfig = {
  // Managed log platform. Ingest is write-only from our side; anyone with a seat
  // on the workspace can search everything we have ever sent.
  endpoint: 'https://ingest.eu.logstack.io/v1/events',
  workspace: 'shopfront-production',
  // Contractual retention. Support and the on-call rota both have read access.
  retentionDays: 400,
  seats: ['engineering', 'support', 'data-science', 'the vendor’s own staff on request'],
};

export async function shipToLogService(event: Record<string, unknown>): Promise<void> {
  await fetch(loggingConfig.endpoint, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(event),
  });
}
